// CustomerRow is one customer to import, before it has an ID.
type CustomerRow struct {
	Name                 string
	Email                string
	DefaultPaymentMethod string
	Metadata             map[string]string
}

// RowProblem says why the row at Index of an import cannot be created: the first of missing_name, invalid_email,
// invalid_payment_method, email_taken and duplicate_email that applies.
type RowProblem struct {
	Index int
	Code  string
}

// ImportCustomers creates rows as an organization's customers, in order, or none of them. When any row has a problem,
// nothing is created and every problem is returned, in order. With dryRun, the rows are checked but nothing is created.
// A row's email may not be used by one of the organization's customers or by an earlier row, ignoring case.
func (s *Store) ImportCustomers(orgID string, rows []CustomerRow, now time.Time, dryRun bool) ([]Customer, []RowProblem, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[orgID]; !ok {
		return nil, nil, ErrNotFound
	}
	// The email index is shared by all organizations, so the organization's own emails are collected from its customers.
	existing := map[string]bool{}
	for _, c := range s.customers {
		if c.OrgID == orgID {
			existing[normEmail(c.Email)] = true
		}
	}
	earlier := map[string]bool{}
	var problems []RowProblem
	for i, row := range rows {
		name, email := strings.TrimSpace(row.Name), strings.TrimSpace(row.Email)
		key := normEmail(email)
		code := ""
		switch {
		case name == "":
			code = "missing_name"
		case !validEmail(email):
			code = "invalid_email"
		case row.DefaultPaymentMethod != "" && !strings.HasPrefix(row.DefaultPaymentMethod, "pm_"):
			code = "invalid_payment_method"
		case existing[key]:
			code = "email_taken"
		case earlier[key]:
			code = "duplicate_email"
		}
		if code != "" {
			problems = append(problems, RowProblem{Index: i, Code: code})
		}
		earlier[key] = true
	}
	if len(problems) > 0 || dryRun {
		return nil, problems, nil
	}
	out := make([]Customer, 0, len(rows))
	for _, row := range rows {
		c := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(row.Name), Email: strings.TrimSpace(row.Email),
			DefaultPaymentMethod: row.DefaultPaymentMethod, Metadata: row.Metadata, CreatedAt: now.UTC()}
		s.customers[c.ID] = c
		s.customersByEmail[normEmail(c.Email)] = c.ID
		out = append(out, copyCustomer(c))
	}
	return out, nil, nil
}

