cat >> internal/api/customers.go <<'EOF'

// importCustomers creates customers from a CSV body. The first record is a header with the columns name and email, and
// may have default_payment_method and metadata.<key> columns. Nothing is created unless every row is fine.
func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, importMaxBytes))
	var tooBig *http.MaxBytesError
	switch {
	case errors.As(err, &tooBig):
		writeError(w, http.StatusRequestEntityTooLarge, "too_large", "the body is larger than 10 MiB")
		return
	case err != nil:
		writeError(w, http.StatusBadRequest, "invalid_csv", "the body could not be read")
		return
	}
	body = bytes.TrimPrefix(body, []byte("\xef\xbb\xbf"))
	if !utf8.Valid(body) {
		writeError(w, http.StatusBadRequest, "invalid_csv", "the body is not UTF-8 text")
		return
	}
	rows, lines, ok := parseCustomerCSV(w, body)
	if !ok {
		return
	}
	dryRun := r.URL.Query().Get("dry_run") == "true"
	cs, problems, err := s.store.ImportCustomers(p.OrgID, rows, s.clock.Now(), dryRun)
	if err != nil {
		s.storeError(w, err)
		return
	}
	if len(problems) > 0 {
		out := make([]importRowError, len(problems))
		for i, pr := range problems {
			out[i] = importRowError{Row: lines[pr.Index], Error: pr.Code}
		}
		writeJSON(w, http.StatusUnprocessableEntity, map[string]any{
			"error": "invalid_rows", "message": "some rows cannot be imported; nothing was created", "rows": out})
		return
	}
	if dryRun {
		writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(rows)})
		return
	}
	for _, c := range cs {
		s.publish(r.Context(), p.OrgID, "customer.created", c)
	}
	writeJSON(w, http.StatusCreated, map[string]any{"created": len(cs), "items": cs})
}

// importRowError is one row of an import that cannot be created. Row is the line where the record starts.
type importRowError struct {
	Row   int    `json:"row"`
	Error string `json:"error"`
}

// parseCustomerCSV reads the header and the data records of a customer import, with the line where each record starts.
// Blank records are skipped. It answers the error and returns false when the body is not usable.
func parseCustomerCSV(w http.ResponseWriter, body []byte) ([]store.CustomerRow, []int, bool) {
	cr := csv.NewReader(bytes.NewReader(body))
	cr.FieldsPerRecord = -1
	var cols *customerColumns
	var rows []store.CustomerRow
	var lines []int
	for {
		rec, err := cr.Read()
		if err == io.EOF {
			break
		}
		if err != nil {
			writeError(w, http.StatusBadRequest, "invalid_csv", "the body is not valid CSV: "+err.Error())
			return nil, nil, false
		}
		if blankRecord(rec) {
			continue
		}
		if cols == nil {
			c := customerColumnsOf(rec)
			if c.name < 0 || c.email < 0 {
				writeError(w, http.StatusUnprocessableEntity, "invalid_header", "the header needs the columns name and email")
				return nil, nil, false
			}
			cols = &c
			continue
		}
		if len(rows) == importMaxRows {
			writeError(w, http.StatusRequestEntityTooLarge, "too_many_rows", "an import creates at most 10,000 customers")
			return nil, nil, false
		}
		line, _ := cr.FieldPos(0)
		rows = append(rows, cols.row(rec))
		lines = append(lines, line)
	}
	if cols == nil {
		writeError(w, http.StatusUnprocessableEntity, "invalid_header", "the body needs a header with the columns name and email")
		return nil, nil, false
	}
	return rows, lines, true
}

// blankRecord reports whether every field of a record is empty or spaces.
func blankRecord(rec []string) bool {
	for _, f := range rec {
		if strings.TrimSpace(f) != "" {
			return false
		}
	}
	return true
}

// customerColumns says which field of a record holds each column of a customer import; -1 when there is no such column.
