func TestImportCustomers(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	e.CreateCustomer(e.Globex, "Gus", "gus@example.com")
	imp := func(query string, body any) *apitest.Response {
		return e.Do("POST", "/v1/customers/import"+query, e.Acme.Key, body)
	}
	count := func() int {
		var l struct{ Items []store.Customer }
		e.MustDo(http.StatusOK, "GET", "/v1/customers", e.Acme.Key, nil, &l)
		return len(l.Items)
	}
	events := func() int {
		var l struct{ Items []store.Event }
		e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", e.Acme.Key, nil, &l)
		return len(l.Items)
	}

	for _, c := range []struct {
		body   string
		status int
		code   string
	}{
		{"", http.StatusUnprocessableEntity, "invalid_header"},
		{"name,phone\nA,1\n", http.StatusUnprocessableEntity, "invalid_header"},
		{"name,email\n\"A,a@x\n", http.StatusBadRequest, "invalid_csv"},
		{"name,email\nA\"b,a@x\n", http.StatusBadRequest, "invalid_csv"},
		{"name,email\n\xff,a@x\n", http.StatusBadRequest, "invalid_csv"},
	} {
		if r := imp("", c.body); r.Code != c.status || r.Map(t)["error"] != c.code {
			t.Fatalf("%q: %s, want %d %s", c.body, r, c.status, c.code)
		}
	}
	if r := imp("", "name,email\n"); r.Code != http.StatusCreated || !strings.Contains(string(r.Body), `"items":[]`) {
		t.Fatalf("header only: %s", r)
	}

	// Columns come in any order; names match ignoring case and spaces; other columns are ignored; a BOM, CRLF line ends and
	// blank lines are fine; quoted fields may hold commas, quotes and line breaks.
	events0 := events()
	body := "﻿ Metadata.CRM ,ignored, Default_Payment_Method ,NAME, EMAIL\r\n" +
		"7,x,pm_1,\"Ann, \"\"the\"\" Lee\",ann@example.com\r\n" +
		"\r\n" +
		"   \r\n" +
		",x,,\"Bo\nBo\",bo@example.com\n"
	var made struct {
		Created int
		Items   []store.Customer
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, body, &made)
	if made.Created != 2 || len(made.Items) != 2 {
		t.Fatalf("created = %+v", made)
	}
	ann, bo := made.Items[0], made.Items[1]
	if ann.Name != `Ann, "the" Lee` || ann.Email != "ann@example.com" || ann.DefaultPaymentMethod != "pm_1" || ann.Metadata["CRM"] != "7" {
		t.Fatalf("ann = %+v", ann)
	}
	if bo.Name != "Bo\nBo" || bo.Email != "bo@example.com" || len(bo.Metadata) != 0 || bo.OrgID != e.Acme.ID {
		t.Fatalf("bo = %+v", bo)
	}
	if n := events(); n != events0+2 {
		t.Fatalf("customer.created events: %d, want %d", n, events0+2)
	}
	if n := count(); n != 3 {
		t.Fatalf("customers after import: %d", n)
	}

	// Another organization's customer does not take an email here.
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "name,email\nGus,gus@example.com\n", &made)
	if made.Created != 1 {
		t.Fatalf("other org's email: %+v", made)
	}

	// Dry run checks the rows and creates nothing.
	var dry struct{ Created, WouldCreate int `json:"would_create"` }
	e.MustDo(http.StatusOK, "POST", "/v1/customers/import?dry_run=true", e.Acme.Key, "name,email\nDry,dry@example.com\n", &dry)
	if dry.Created != 0 || dry.WouldCreate != 1 || count() != 4 {
		t.Fatalf("dry run = %+v, customers %d", dry, count())
	}

	// Every bad row is listed with the line where it starts (quoted line breaks count), with the first problem that applies.
	bad := "name,email,default_payment_method\n" +
		",nobody@example.com,\n" + // 2: missing_name
		"Cy,not-an-email,\n" + // 3: invalid_email
		"Di,di@example.com,card_1\n" + // 4: invalid_payment_method
		"Ed,JANE@example.com,\n" + // 5: email_taken
		"\"Fi\nFi\",fi@example.com,\n" + // 6-7: fine
		"Gi,FI@example.com,\n" + // 8: duplicate_email
		",FI@example.com,\n" // 9: missing_name comes before duplicate_email
	var invalid struct {
		Error string
		Rows  []struct {
			Row   int
			Error string
		}
	}
	r := imp("", bad)
	r.JSON(t, &invalid)
	if r.Code != http.StatusUnprocessableEntity || invalid.Error != "invalid_rows" {
		t.Fatalf("bad rows: %s", r)
	}
	want := []struct {
		row  int
		code string
	}{{2, "missing_name"}, {3, "invalid_email"}, {4, "invalid_payment_method"}, {5, "email_taken"}, {8, "duplicate_email"}, {9, "missing_name"}}
	if len(invalid.Rows) != len(want) {
		t.Fatalf("rows = %+v", invalid.Rows)
	}
	for i, w := range want {
		if got := invalid.Rows[i]; got.Row != w.row || got.Error != w.code {
			t.Fatalf("row %d = %+v, want %+v", i, got, w)
		}
	}
	if count() != 4 {
		t.Fatalf("nothing may be created: %d customers", count())
	}
	if r := imp("?dry_run=true", bad); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("dry run of bad rows: %s", r)
	}

	// At most 10,000 data records.
	var big strings.Builder
	big.WriteString("name,email\n")
	for i := range 10001 {
		fmt.Fprintf(&big, "C%d,c%d@example.com\n", i, i)
	}
	if r := imp("", big.String()); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
		t.Fatalf("10,001 rows: %s", r)
	}
	full := strings.SplitAfter(big.String(), "\n")
	if r := imp("?dry_run=true", strings.Join(full[:10001], "")); r.Code != http.StatusOK || r.Map(t)["would_create"] != float64(10000) {
		t.Fatalf("10,000 rows: %s", r)
	}
	if count() != 4 {
		t.Fatalf("customers changed: %d", count())
	}
}

