144	// importCustomers creates customers from a CSV body. The first record is a header with the columns name and email, and
145	// may have default_payment_method and metadata.<key> columns. Nothing is created unless every row is fine.
146	func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
147		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, importMaxBytes))
148		var tooBig *http.MaxBytesError
149		switch {
150		case errors.As(err, &tooBig):
151			writeError(w, http.StatusRequestEntityTooLarge, "too_large", "the body is larger than 10 MiB")
152			return
153		case err != nil:
154			writeError(w, http.StatusBadRequest, "invalid_csv", "the body could not be read")
155			return
156		}
157		body = bytes.TrimPrefix(body, []byte("\xef\xbb\xbf"))
158		if !utf8.Valid(body) {
159			writeError(w, http.StatusBadRequest, "invalid_csv", "the body is not UTF-8 text")
160			return
161		}
162		rows, lines, ok := parseCustomerCSV(w, body)
163		if !ok {
164			return
165		}
166		dryRun := r.URL.Query().Get("dry_run") == "true"
167		cs, problems, err := s.store.ImportCustomers(p.OrgID, rows, s.clock.Now(), dryRun)
168		if err != nil {
169			s.storeError(w, err)
170			return
171		}
172		if len(problems) > 0 {
173			out := make([]importRowError, len(problems))
174			for i, pr := range problems {
175				out[i] = importRowError{Row: lines[pr.Index], Error: pr.Code}
176			}
177			writeJSON(w, http.StatusUnprocessableEntity, map[string]any{
178				"error": "invalid_rows", "message": "some rows cannot be imported; nothing was created", "rows": out})
179			return
180		}
181		if dryRun {
182			writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(rows)})
183			return
184		}
185		for _, c := range cs {
186			s.publish(r.Context(), p.OrgID, "customer.created", c)
187		}
188		writeJSON(w, http.StatusCreated, map[string]any{"created": len(cs), "items": cs})
189	}
