191	// importRowError is one row of an import that cannot be created. Row is the line where the record starts.
192	type importRowError struct {
193		Row   int    `json:"row"`
194		Error string `json:"error"`
195	}
196	
197	// parseCustomerCSV reads the header and the data records of a customer import, with the line where each record starts.
198	// Blank records are skipped. It answers the error and returns false when the body is not usable.
199	func parseCustomerCSV(w http.ResponseWriter, body []byte) ([]store.CustomerRow, []int, bool) {
200		cr := csv.NewReader(bytes.NewReader(body))
201		cr.FieldsPerRecord = -1
202		var cols *customerColumns
203		var rows []store.CustomerRow
204		var lines []int
205		for {
206			rec, err := cr.Read()
207			if err == io.EOF {
208				break
209			}
210			if err != nil {
211				writeError(w, http.StatusBadRequest, "invalid_csv", "the body is not valid CSV: "+err.Error())
212				return nil, nil, false
213			}
214			if blankRecord(rec) {
215				continue
216			}
217			if cols == nil {
218				c := customerColumnsOf(rec)
219				if c.name < 0 || c.email < 0 {
220					writeError(w, http.StatusUnprocessableEntity, "invalid_header", "the header needs the columns name and email")
221					return nil, nil, false
222				}
223				cols = &c
224				continue
225			}
226			if len(rows) == importMaxRows {
227				writeError(w, http.StatusRequestEntityTooLarge, "too_many_rows", "an import creates at most 10,000 customers")
228				return nil, nil, false
229			}
230			line, _ := cr.FieldPos(0)
231			rows = append(rows, cols.row(rec))
232			lines = append(lines, line)
233		}
234		if cols == nil {
235			writeError(w, http.StatusUnprocessableEntity, "invalid_header", "the body needs a header with the columns name and email")
236			return nil, nil, false
237		}
238		return rows, lines, true
239	}
